x_comment(x_indirectlyConstrainedFrames,"(indirectlyConstrainedFrames ?qf1 ?qf2 ?sign ?sid) two quantity frames (?qf1 and ?qf2) can be in a qprop if one\n changes as the other changes. In such a relationship ?qf1 is the consequent (constrained) and ?qf2 is the antecedent (constrainer).\n The co-varying relationship is found through a call to inDecEvents. The sign is the sign of the qprop. The evidence is in sentence ?sid") :- x_cid(a65b12696eadfe).
